# Run from an elevated PowerShell. Generated by your authenticated RRM instance.
$ErrorActionPreference = 'Stop'
if (-not ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) { throw 'PowerShell als Administrator öffnen.' }
$setup = @'
__SETUP__
'@ | ConvertFrom-Json
$root = Join-Path $env:ProgramData 'RRM-Agent'
New-Item -ItemType Directory -Force -Path $root | Out-Null
& icacls $root /inheritance:r /grant:r '*S-1-5-18:(OI)(CI)F' '*S-1-5-32-544:(OI)(CI)F' | Out-Null
if ($LASTEXITCODE -ne 0) { throw 'Konfigurationsverzeichnis konnte nicht geschützt werden.' }
$zip = Join-Path $root 'download.zip'
Invoke-WebRequest -Uri $setup.download_url -OutFile $zip -UseBasicParsing
if ((Get-FileHash -LiteralPath $zip -Algorithm SHA256).Hash.ToLowerInvariant() -ne $setup.sha256) { throw 'Paket-Prüfsumme falsch.' }
$stage = Join-Path $root ('bootstrap-' + $setup.config.version)
Expand-Archive -LiteralPath $zip -DestinationPath $stage -Force
$config = Join-Path $root 'config.json'
$setup.config | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $config -Encoding UTF8
# Windows PowerShell writes a UTF-8 BOM; the agent accepts utf-8-sig.
& (Join-Path $stage 'rrm-agent.exe') --install --config $config
if ($LASTEXITCODE -ne 0) { throw 'Agent-Installation fehlgeschlagen.' }
Remove-Item -LiteralPath $zip
Write-Output 'RRM-Agent installiert. Updateprüfung: alle 15 Minuten. Der Host erscheint innerhalb einer Minute.'
